meta.script:
// nearadin.net Sürekli Güncellenen Dinamik Trend Havuzu
const dinamikTrendler = [
    "Yapay Zeka Araçları", "Python ile Veri Analizi", "SEO Uyumlu Web Tasarım",
    "React 19 Yenilikleri", "Gram Altın Piyasası", "Uzaktan Çalışma Trendleri",
    "Girişimcilik ve Yazılım", "BIST 100 Analizleri", "Siber Güvenlik Rehberi",
    "Mobil Uygulama Geliştirme", "Bulut Bilişim Sistemleri", "Dijital Pazarlama Stratejileri",
    "Kripto Para Gelişmeleri", "Modern Yazılım Mimarileri", "Elektrikli Araç Teknolojileri"
];

window.addEventListener('DOMContentLoaded', () => {
    const bugun = new Date().toISOString().split('T')[0];
    const baseUrl = "https://nearadin.net/detaylar/?q=";

    let xml = `\n`;
    xml += `\n`;

    // Ana Sayfa
    xml += `  \n`;
    xml += `    https://nearadin.net/\n`;
    xml += `    ${bugun}\n`;
    xml += `    always\n`;
    xml += `    1.0\n`;
    xml += `  \n`;

    // Dinamik Trend Aramaları
    dinamikTrendler.forEach(trend => {
        xml += `  \n`;
        xml += `    ${baseUrl}${encodeURIComponent(trend)}\n`;
        xml += `    ${bugun}\n`;
        xml += `    hourly\n`;
        xml += `    0.8\n`;
    });

    xml += ``;

    // Sayfanın içeriğini doğrudan XML olarak tarayıcıya ve Googlebot'a ver
    document.open();
    document.write('' + 
        xml.replace(/&/g, '&').replace(//g, '>') + 
        '');
    document.close();
    document.contentType = "application/xml";
});
